window.STORY_CHAPTERS["ce34a6f60a01ab24c"]={"id":"ce34a6f60a01ab24c","lines":[{"uid":"talk.vc.home_etc_administrator_2#originalText","id":"talk.vc.home_etc_administrator_2","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"有某个属名给你的东西送来了。记得要确实报告内容物。","en":"Something has arrived for you. Make sure you check its contents.","ja":"あなた宛に何か届いているわねきちんと中身を報告するように"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_administrator_3#originalText","id":"talk.vc.home_etc_administrator_3","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"有下一个任务，你要尽快确认。","en":"Your next mission is in. Make sure you confirm it in a timely manner.","ja":"次の任務よ至急確認するように"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_agil_1#originalText","id":"talk.vc.home_etc_agil_1","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"达成使命了，好像还有报酬喔。","en":"You cleared the Mission! Looks like you got a reward.","ja":"ミッション達成だ報酬もあるみたいだな"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_agil_2#originalText","id":"talk.vc.home_etc_agil_2","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"这是指名给你的礼物，你真的很有两把刷子呢。","en":"A present arrived for you. You're a guy no one should underestimate.","ja":"お前宛のプレゼントだなかなか隅に置けないな"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_agil_3#originalText","id":"talk.vc.home_etc_agil_3","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"好像又有新使命啰。","en":"You've got a new Mission.","ja":"また新しいミッションがあるみたいだぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_airy_1#originalText","id":"talk.vc.home_etc_airy_1","speaker":{"cn":"升降员","en":"Operator","ja":"昇降係"},"text":{"cn":"奖励品似乎已经送来了。","en":"You have received a reward.","ja":"報奨品が届いているようです"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_airy_2#originalText","id":"talk.vc.home_etc_airy_2","speaker":{"cn":"升降员","en":"Operator","ja":"昇降係"},"text":{"cn":"有礼物送来了。","en":"A gift arrived for you.","ja":"贈り物が届いております"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_airy_3#originalText","id":"talk.vc.home_etc_airy_3","speaker":{"cn":"升降员","en":"Operator","ja":"昇降係"},"text":{"cn":"好像又传来了新使命呢。","en":"A new mission has arrived.","ja":"また、新たな使命が下されたようですね"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_airy_coverall_1#originalText","id":"talk.vc.home_etc_airy_coverall_1","speaker":{"cn":"艾莉","en":"Airy","ja":"エアリー"},"text":{"cn":"奖励品似乎已经送来了。","en":"You have received a reward.","ja":"報奨品が届いているようです"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_airy_coverall_2#originalText","id":"talk.vc.home_etc_airy_coverall_2","speaker":{"cn":"艾莉","en":"Airy","ja":"エアリー"},"text":{"cn":"有礼物送来了。","en":"A gift arrived for you.","ja":"贈り物が届いております"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_airy_coverall_3#originalText","id":"talk.vc.home_etc_airy_coverall_3","speaker":{"cn":"艾莉","en":"Airy","ja":"エアリー"},"text":{"cn":"好像又传来了新使命呢。","en":"A new mission has arrived.","ja":"また、新たな使命が下されたようですね"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_alice_1#originalText","id":"talk.vc.home_etc_alice_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"达成使命了呢，你就大方收下奖励吧。","en":"You have accomplished the mission. You should claim your prize. You have earned it.","ja":"使命を終えたのですね報奨も遠慮せずに受け取っておきなさい"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_alice_2#originalText","id":"talk.vc.home_etc_alice_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"给你的礼物送来了。赶紧确认比较好吧？","en":"You have received a gift. Shouldn't you open it now?","ja":"お前への贈り物が届いています今すぐ確認したらどうですか？"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_alice_3#originalText","id":"talk.vc.home_etc_alice_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"已经收到下一个使命啰。如果是你，一定可以达成吧。","en":"You have received a new mission. I am confident that you will pass with flying colors.","ja":"次の使命が下されましたよお前なら、きっと達成できるでしょう"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_alice_child_1#originalText","id":"talk.vc.home_etc_alice_child_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"工作做得很顺利对吧？那不是很好吗！","en":"Your work went well, didn't it? Good for you!","ja":"お仕事がうまくいったんでしょ? よかったじゃない! "},"kind":"dialogue"},{"uid":"talk.vc.home_etc_alice_child_2#originalText","id":"talk.vc.home_etc_alice_child_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"礼物送来啰。打开的时候，都会很紧张呢。","en":"A gift arrived for you. Opening gifts is always exciting, isn't it?","ja":"贈り物が届いてるわ開ける時って、ドキドキするわよね"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_alice_child_3#originalText","id":"talk.vc.home_etc_alice_child_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"你要开始新工作了对吧，我也会帮忙的！","en":"A new task arrived, I see. Don't worry, I'll help!","ja":"新しいお仕事が始まるのね私もお手伝いするからね!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_alicia_1#originalText","id":"talk.vc.home_etc_alicia_1","speaker":{"cn":"亚丽莎","en":"Alicia","ja":"アリシャ"},"text":{"cn":"达成使命～！好厉害，好厉害！","en":"Mission accomplished! You're my hero!","ja":"ミッション達成ー!すごいすごい!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_alicia_2#originalText","id":"talk.vc.home_etc_alicia_2","speaker":{"cn":"亚丽莎","en":"Alicia","ja":"アリシャ"},"text":{"cn":"听说有礼物！快打开来看看！","en":"You've got a present. Hurry and open it!","ja":"プレゼントだって!早く開けてみてヨ!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_alicia_3#originalText","id":"talk.vc.home_etc_alicia_3","speaker":{"cn":"亚丽莎","en":"Alicia","ja":"アリシャ"},"text":{"cn":"好像有新任务耶？","en":"I hear a new Quest just came in.","ja":"なんか新しいクエストがあるみたいだヨ?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_argo_1#originalText","id":"talk.vc.home_etc_argo_1","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"你完成使命了呢，能不能告诉我报酬的情报啊？","en":"You cleared the Mission. Will you tell me what the reward is?","ja":"ミッションクリアダナ報酬の情報、教えてくれないカ?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_argo_2#originalText","id":"talk.vc.home_etc_argo_2","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"说是礼物耶，要好好确认是谁送的才行啊。","en":"You got a gift. You should check who sent it to you.","ja":"贈り物だってヨ送り主は、ちゃんとチェックしておかないとナ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_argo_3#originalText","id":"talk.vc.home_etc_argo_3","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"有新任务的情报，这次就特别算你免费吧。","en":"Got some news for you: there's a new Quest out. That info was on the house.","ja":"新しいクエストの情報だ特別にロハにしておくヨ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_asuna_1#originalText","id":"talk.vc.home_etc_asuna_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"恭喜你达成使命。很辛苦吧？","en":"Congrats on clearing that Mission! Wasn't it tough?","ja":"ミッション達成おめでとう大変だったんじゃない? "},"kind":"dialogue"},{"uid":"talk.vc.home_etc_asuna_2#originalText","id":"talk.vc.home_etc_asuna_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"好像有礼物，是谁送的呢？","en":"You've got a present. Who could it be from?","ja":"プレゼントが来てるみたい誰からだろうね"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_asuna_3#originalText","id":"talk.vc.home_etc_asuna_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"听说有新的任务！我们去确认内容吧。","en":"A new Quest came in! Let's go see what it is.","ja":"新しいクエストだって! 内容を確認しに行きましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_azurica_1#originalText","id":"talk.vc.home_etc_azurica_1","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"你出色地完成修练了呢，奖励是属于你的。","en":"You completed your drill with flying colors. You earned this reward.","ja":"見事に修練を終えましたね報奨はあなたのものです"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_azurica_2#originalText","id":"talk.vc.home_etc_azurica_2","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"有属名给你的东西送来了喔。","en":"A gift has arrived for you.","ja":"あなた宛に何か届いていましたよ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_azurica_3#originalText","id":"talk.vc.home_etc_azurica_3","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"来，下一次修练的时间到了，快去确认内容吧。","en":"It is time for your next drill. Please read the details carefully.","ja":"さあ、次の修練の時間です内容を確認しなさい"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_bercouli_1#originalText","id":"talk.vc.home_etc_bercouli_1","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"任务完成，辛苦你啦。","en":"Mission accomplished. Well done.","ja":"任務達成、ご苦労だったな"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_bercouli_2#originalText","id":"talk.vc.home_etc_bercouli_2","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"这个礼物……好像是给你的。","en":"This gift is...addressed to you, apparently.","ja":"この贈り物は……お前さん宛みたいだな"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_bercouli_3#originalText","id":"talk.vc.home_etc_bercouli_3","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"听说有下一个任务，去三两下解决它吧。","en":"A new mission arrived. Let's go take care of it.","ja":"次の任務だってよとっとと片付けちまうか"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_cardinal_1#originalText","id":"talk.vc.home_etc_cardinal_1","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"看来你顺利完成工作了。别忘了领取报酬啊。","en":"You have completed a task, I hear. You should claim your reward.","ja":"仕事を無事に終えたようじゃな報酬は忘れずに受け取っておくのじゃぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_cardinal_2#originalText","id":"talk.vc.home_etc_cardinal_2","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"你也很受欢迎呢，有礼物送来了。","en":"You seem to be quite popular. You've received a gift.","ja":"お主もなかなか人気があるな贈り物が届いておる"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_cardinal_3#originalText","id":"talk.vc.home_etc_cardinal_3","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"下一份工作已经决定啰！好了，快出发吧！","en":"A new task has arrived! Now, you must go complete it!","ja":"次の仕事が決まったぞ!さあ、行ってくるんじゃ!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_dakira_1#originalText","id":"talk.vc.home_etc_dakira_1","speaker":{"cn":"达基拉","en":"Dakira","ja":"ダキラ"},"text":{"cn":"恭喜您达成使命。","en":"Congratulations on accomplishing the mission!","ja":"使命の達成、おめでとうございます"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_dakira_2#originalText","id":"talk.vc.home_etc_dakira_2","speaker":{"cn":"达基拉","en":"Dakira","ja":"ダキラ"},"text":{"cn":"有礼物送抵，要我帮您拿过来吗？","en":"A gift arrived for you. Would you like me to go fetch it?","ja":"贈り物が届いておりますお持ちいたしましょうか?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_dakira_3#originalText","id":"talk.vc.home_etc_dakira_3","speaker":{"cn":"达基拉","en":"Dakira","ja":"ダキラ"},"text":{"cn":"好像有下一个任务呢。若您不嫌弃，请让我与您同行！","en":"The next mission has arrived. I would love to accompany you, if I may!","ja":"次なる任務があるようですねよろしければ、お供させてください!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_deathgun_1#originalText","id":"talk.vc.home_etc_deathgun_1","speaker":{"cn":"死枪","en":"Death Gun","ja":"デス・ガン"},"text":{"cn":"完成、了吗？就你、而言、做得、还不错。","en":"Did you clear the Mission? Well done!","ja":"クリア、したかお前に、しては、上出来だ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_deathgun_2#originalText","id":"talk.vc.home_etc_deathgun_2","speaker":{"cn":"死枪","en":"Death Gun","ja":"デス・ガン"},"text":{"cn":"我送你的、礼物，总有一天、会用、这把枪、送到、你手上的。","en":"Eventually I'll give you a taste of this gun as a present.","ja":"俺からの、贈り物はいずれ、この銃で届けて、やろう"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_deathgun_3#originalText","id":"talk.vc.home_etc_deathgun_3","speaker":{"cn":"死枪","en":"Death Gun","ja":"デス・ガン"},"text":{"cn":"等等、要去、哪里？不管、去哪我都会、追上、然后、杀掉。","en":"Where should we go next? Let's follow them to the ends of the world and beat them down!","ja":"次は、どこへ、行く?どこまでも、追いかけて殺して、やろう"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_deusolbert_1#originalText","id":"talk.vc.home_etc_deusolbert_1","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"任务完成了。有劳你了。","en":"Mission accomplished. Well done.","ja":"任務完了だご苦労だったな"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_deusolbert_2#originalText","id":"talk.vc.home_etc_deusolbert_2","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"有寄给你的货物喔，快去收下吧。","en":"A gift has arrived for you. Go fetch it at once.","ja":"貴様宛の荷物があるぞ早く受け取ってこい"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_deusolbert_3#originalText","id":"talk.vc.home_etc_deusolbert_3","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"下一份任务交付下来了。你准备好了吗？","en":"A new mission has arrived. Are you ready for it?","ja":"次なる任務が与えられた準備はいいか?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_diavel_1#originalText","id":"talk.vc.home_etc_diavel_1","speaker":{"cn":"迪亚贝尔","en":"Diavel","ja":"ディアベル"},"text":{"cn":"完成使命的报酬送来啰。","en":"You've got a reward for clearing the Mission.","ja":"ミッションの報酬が届いてるぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_diavel_2#originalText","id":"talk.vc.home_etc_diavel_2","speaker":{"cn":"迪亚贝尔","en":"Diavel","ja":"ディアベル"},"text":{"cn":"好像有你的礼物送来，你真的很有两把刷子呢。","en":"A present arrived for you. You're a guy no one should underestimate.","ja":"君にプレゼントが来てるみたいだなかなか隅に置けないな"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_diavel_3#originalText","id":"talk.vc.home_etc_diavel_3","speaker":{"cn":"迪亚贝尔","en":"Diavel","ja":"ディアベル"},"text":{"cn":"好像有新任务，必须去确认才行！","en":"A new Quest just came out. Let's check it out!","ja":"新しくクエストがあるみたいだチェックしないとな!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_dil_1#originalText","id":"talk.vc.home_etc_dil_1","speaker":{"cn":"蒂伊‧艾‧耶尔","en":"Dee Eye Ell","ja":"ディー・アイ・エル"},"text":{"cn":"远征辛苦了。不愧是陛下，非常完美。","en":"Bravo, for your excellent expedition! Your majesty is without a doubt, perfection.","ja":"遠征お疲れ様でございましたさすがは陛下、完璧です"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_dil_2#originalText","id":"talk.vc.home_etc_dil_2","speaker":{"cn":"蒂伊‧艾‧耶尔","en":"Dee Eye Ell","ja":"ディー・アイ・エル"},"text":{"cn":"有给陛下的贡品。里面的所有东西我都已经确认过是安全的。","en":"A present has arrived for your majesty. Of course, I have personally checked the contents myself and can confirm that it is completely safe.","ja":"陛下への貢ぎ物が届いております無論、中身はすべて私が確認し安全を確かめております"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_dil_3#originalText","id":"talk.vc.home_etc_dil_3","speaker":{"cn":"蒂伊‧艾‧耶尔","en":"Dee Eye Ell","ja":"ディー・アイ・エル"},"text":{"cn":"下次的目标已经决定好了吗？如果已经决定好，请交给我指挥。","en":"Have you decided on what the next target will be? Please leave the command to me.","ja":"次の目標がお決まりですか?なれば、指揮は私にお任せください"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_edith_1#originalText","id":"talk.vc.home_etc_edith_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"任务达成！好像有奖励呢！","en":"Mission accomplished! I hear a reward is waiting for you.","ja":"任務達成! ご褒美が待ってるみたいだよ! "},"kind":"dialogue"},{"uid":"talk.vc.home_etc_edith_2#originalText","id":"talk.vc.home_etc_edith_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"有礼物送来了。欸，里面放什么？告诉我嘛。","en":"A gift arrived for you. Won't you tell me what it is?","ja":"贈り物が届いてるねねえ、何が贈られてきたか教えてよ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_edith_3#originalText","id":"talk.vc.home_etc_edith_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"听说有新任务。去随手解决它吧。","en":"A new mission arrived. Let's go take care of it.","ja":"新しい任務だって軽く片付けちゃおうか"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_egome_1#originalText","id":"talk.vc.home_etc_egome_1","speaker":{"cn":"伊格姆","en":"Egome","ja":"イゴーム"},"text":{"cn":"这好像是达成使命的奖励。下次我一定也要……","en":"I hear you got a reward for a mission accomplished. Next time it will be me...","ja":"使命達成の報奨だそうだ次こそは俺も……"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_egome_2#originalText","id":"talk.vc.home_etc_egome_2","speaker":{"cn":"伊格姆","en":"Egome","ja":"イゴーム"},"text":{"cn":"给你的礼物？就没有给我的吗？","en":"A gift arrived for you. Isn't there one for me?","ja":"お前宛の贈り物?俺宛のはないのか?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_egome_3#originalText","id":"talk.vc.home_etc_egome_3","speaker":{"cn":"伊格姆","en":"Egome","ja":"イゴーム"},"text":{"cn":"下一份工作由我来做。你就看着吧。","en":"I've got the next assignment. You just watch and learn something.","ja":"次の仕事は、俺がやってやるお前は見てな"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_eiji_1#originalText","id":"talk.vc.home_etc_eiji_1","speaker":{"cn":"瑛二","en":"Eiji","ja":"エイジ"},"text":{"cn":"恭喜你完成使命。你的成长真令人吃惊。","en":"Congratulations on clearing the Mission! I've been thorougly impressed with how much you've grown.","ja":"ミッションクリア、おめでとう君の成長には、まったく驚かされるよ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_eiji_2#originalText","id":"talk.vc.home_etc_eiji_2","speaker":{"cn":"瑛二","en":"Eiji","ja":"エイジ"},"text":{"cn":"有署名给你的礼物。呵呵，如果送的人看到你这么开心，一定也很开心吧。","en":"There's a present with your name on it. Fufu, if that alone makes you happy I'm sure the sender would be as well.","ja":"君宛のプレゼントがあるふふ、それだけ喜ばれると贈った人もうれしいだろうな"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_eiji_3#originalText","id":"talk.vc.home_etc_eiji_3","speaker":{"cn":"瑛二","en":"Eiji","ja":"エイジ"},"text":{"cn":"听说有新任务。我想你一定有兴趣。","en":"I hear a new Quest just came in. There is sure to be some interest in it I think.","ja":"新しいクエストがあるみたいだきっと興味があると思ってね"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_eldrie_1#originalText","id":"talk.vc.home_etc_eldrie_1","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"您平安达成任务，令我欣慰至极。","en":"I am truly proud of you for completing your mission.","ja":"任務、無事に達成されたとのこと誠に重畳に存じます"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_eldrie_2#originalText","id":"talk.vc.home_etc_eldrie_2","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"这是礼物吗？那么本人艾尔多利耶，就来确认其中是否有危险吧……","en":"A gift? Well, let me check to see that we are not in danger.","ja":"贈り物ですか?ならばこのエルドリエが危険がないか確認を……"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_eldrie_3#originalText","id":"talk.vc.home_etc_eldrie_3","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"下一个任务来了。本人艾尔多利耶，愿替您一效棉薄之力。","en":"The next mission has arrived. I would be honored to aid you.","ja":"次なる任務が与えられました微力ながら、このエルドリエも助力させていただきます"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_entokia_integrator_1#originalText","id":"talk.vc.home_etc_entokia_integrator_1","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"工作辛苦啦。这次的工作怎么样？办起来有意思吗？","en":"A job well done, Master! What was your mission today? Did you enjoy yourself?","ja":"お仕事お疲れさまっす今回の仕事はどうでした?楽しかったっすか?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_entokia_integrator_2#originalText","id":"talk.vc.home_etc_entokia_integrator_2","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"老师，有你的礼物喔。反正肯定是女生送的吧？毕竟你身边美女如云啊。","en":"Present for you, Master. From a girl, I assume? You're always surrounded by beauties.","ja":"先生に贈り物が来てますよどうせ女の子からでしょ?先生の周りは美人ばっかりだから"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_entokia_integrator_3#originalText","id":"talk.vc.home_etc_entokia_integrator_3","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"老师，下个工作来了。这次我也来帮忙吧，你觉得呢？","en":"Looks like you have a new mission, Master. May I assist you this time?","ja":"先生、次の仕事が来ました今回は、オレもお手伝いしましょうか?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_eugene_1#originalText","id":"talk.vc.home_etc_eugene_1","speaker":{"cn":"尤金","en":"Eugene","ja":"ユージーン"},"text":{"cn":"有使命报酬喔，都是你的功劳啊。","en":"You've got a reward for clearing the Mission. The credit is all yours.","ja":"ミッション報酬があるぞお前の手柄だ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_eugene_2#originalText","id":"talk.vc.home_etc_eugene_2","speaker":{"cn":"尤金","en":"Eugene","ja":"ユージーン"},"text":{"cn":"好像有礼物送来了。","en":"Looks like you got a present.","ja":"プレゼントが来ているようだ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_eugene_3#originalText","id":"talk.vc.home_etc_eugene_3","speaker":{"cn":"尤金","en":"Eugene","ja":"ユージーン"},"text":{"cn":"好像有新任务，要一起去吗？","en":"A new mission just came in. Wanna do it together?","ja":"新しい任務があるようだ一緒に行くか?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_eugeo_1#originalText","id":"talk.vc.home_etc_eugeo_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"达成使命了呢，Stay cool！……咦，我用错了吗？","en":"Mission accomplished. Stay cool! Huh? I used the phrase incorrectly?","ja":"使命達成だね、ステイクール! ……え、使い方が違うの? "},"kind":"dialogue"},{"uid":"talk.vc.home_etc_eugeo_2#originalText","id":"talk.vc.home_etc_eugeo_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"礼物送来了，你要记得快点去确认喔。","en":"You got a gift! You should check it out sooner rather than later.","ja":"贈り物が届いているよちゃんと早めに確認しなよ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_eugeo_3#originalText","id":"talk.vc.home_etc_eugeo_3","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"好像有新的使命，我们去确认吧？","en":"Looks like we have a new mission. Let's check it out.","ja":"新しい使命があるみたいだ確認しに行こうか"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_eugeo_child_1#originalText","id":"talk.vc.home_etc_eugeo_child_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"你看，好像有奖励呢。听说是因为完成了工作。","en":"Looks like you have a reward coming your way! It's because you finished your job.","ja":"ほら、なんかご褒美あるみたいだよ仕事を終えたから、だって"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_eugeo_child_2#originalText","id":"talk.vc.home_etc_eugeo_child_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"礼物送来啰。你还真是受欢迎呢。","en":"You got a gift. Look who's popular!","ja":"贈り物が届いているよ人気者だなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_eugeo_child_3#originalText","id":"talk.vc.home_etc_eugeo_child_3","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"下一份工作好像决定好了，我们去确认吧。","en":"Looks like we have a new job. Let's check it out.","ja":"次の仕事が決まったみたいだ確認しに行こうか"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_fanatio_1#originalText","id":"talk.vc.home_etc_fanatio_1","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"达成任务了呢。听闻奖励已备妥。","en":"Mission accomplished. There is a reward for you.","ja":"任務達成ですね報奨が用意されているとのことです"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_fanatio_2#originalText","id":"talk.vc.home_etc_fanatio_2","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"礼物……是谁送的呢？","en":"A gift... Who is it from?","ja":"贈り物……どなたからですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_fanatio_3#originalText","id":"talk.vc.home_etc_fanatio_3","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"发表下一个任务了啊，是什么内容呢？","en":"You have a new mission. I wonder what it entails?","ja":"次の任務が発表されましたねどんな内容でしょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_fizel_1#originalText","id":"talk.vc.home_etc_fizel_1","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"达成使命了，很行嘛。","en":"Mission accomplished. Well done.","ja":"使命達成ね、やるじゃない"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_fizel_2#originalText","id":"talk.vc.home_etc_fizel_2","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"有礼物喔，还不打开来看看？","en":"You've received a gift. Maybe open it?","ja":"贈り物よ早く開けてみたら?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_fizel_3#originalText","id":"talk.vc.home_etc_fizel_3","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"新任务？又是立功的好机会呢。真羡慕。","en":"A new mission? Another chance to prove your merit. Lucky you.","ja":"新しい任務?また手柄を上げられるわねいいなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_frenica_1#originalText","id":"talk.vc.home_etc_frenica_1","speaker":{"cn":"芙蕾妮卡","en":"Frenica","ja":"フレニーカ"},"text":{"cn":"修练结束了吗？真厉害，我也不能输呢。","en":"You already finished your assignment? Wow, I'm impressed. I need to catch up.","ja":"修練、もう終わったの?さすがだね、私も負けてられないな"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_frenica_2#originalText","id":"talk.vc.home_etc_frenica_2","speaker":{"cn":"芙蕾妮卡","en":"Frenica","ja":"フレニーカ"},"text":{"cn":"你看，好像有礼物呢。欸欸，是谁送的啊？","en":"Look, a gift arrived for you. So, who's it from?","ja":"ほら、贈り物があるみたいねえねえ、誰からなの?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_frenica_3#originalText","id":"talk.vc.home_etc_frenica_3","speaker":{"cn":"芙蕾妮卡","en":"Frenica","ja":"フレニーカ"},"text":{"cn":"是下一次修练的时间啊，下次也要加油喔！","en":"It's time for a new assignment. Good luck!","ja":"次の修練の時間だね次も頑張ろうね!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_geero_1#originalText","id":"talk.vc.home_etc_geero_1","speaker":{"cn":"吉罗","en":"Geero","ja":"ジーロ"},"text":{"cn":"恭喜您达成使命","en":"Congrats on completing your mission.","ja":"使命達成おめでとうございます"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_geero_2#originalText","id":"talk.vc.home_etc_geero_2","speaker":{"cn":"吉罗","en":"Geero","ja":"ジーロ"},"text":{"cn":"报告礼物已经送到了","en":"Reporting in. A present has arrived.","ja":"報告いたします贈り物がこちらに届きました"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_geero_3#originalText","id":"talk.vc.home_etc_geero_3","speaker":{"cn":"吉罗","en":"Geero","ja":"ジーロ"},"text":{"cn":"下次的任务好像定了请务必带我们一起去","en":"We got another mission. We’d love for you to join us.","ja":"次の任務が決まったようですぜひ我らをお連れください"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_golgorosso_1#originalText","id":"talk.vc.home_etc_golgorosso_1","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"看来你漂亮地达成使命啦？我真是没看走眼。","en":"You fulfilled your mission. I knew you could do it.","ja":"見事に使命を達成したそうだな俺の見込み通りだ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_golgorosso_2#originalText","id":"talk.vc.home_etc_golgorosso_2","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"有东西寄给你喔，打开来看看吧。","en":"A package has arrived for you. You should open it!","ja":"お前になにか届いているぞ開けてみたらどうだ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_golgorosso_3#originalText","id":"talk.vc.home_etc_golgorosso_3","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"好，是下一个使命。我们走！","en":"The next assignment is in. Let's go!","ja":"よし、次の使命だ行くぞ!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_heathcliff_1#originalText","id":"talk.vc.home_etc_heathcliff_1","speaker":{"cn":"希兹克利夫","en":"Heathcliff","ja":"ヒースクリフ"},"text":{"cn":"达成使命了吗？干得漂亮。你果然是我们的公会所需的人才。","en":"Clearing that Mission was splendid! You are definitely the kind of player we're looking for in the guild!","ja":"ミッション達成か、見事だやはり、うちのギルドにほしい人材だな"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_heathcliff_2#originalText","id":"talk.vc.home_etc_heathcliff_2","speaker":{"cn":"希兹克利夫","en":"Heathcliff","ja":"ヒースクリフ"},"text":{"cn":"不是还有没拆的礼物吗？我认为早点去确认比较好。","en":"Don't you have an un-opened gift? I think you should hurry up and find out what's inside.","ja":"未開封のギフトがあるんじゃないか?早めに確認した方がいいと思うがね"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_heathcliff_3#originalText","id":"talk.vc.home_etc_heathcliff_3","speaker":{"cn":"希兹克利夫","en":"Heathcliff","ja":"ヒースクリフ"},"text":{"cn":"已经开放下一个任务了。身为攻略组，在意新任务是理所当然的吧？","en":"The next quest has been unlocked. Isn't that something you should be interested in, as a member of the strategy council?","ja":"次のクエストが解放された攻略組としては、気になるところだろう?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_hoveren_1#originalText","id":"talk.vc.home_etc_hoveren_1","speaker":{"cn":"何布雷恩","en":"Hoveren","ja":"ホーブレン"},"text":{"cn":"您完成使命了吗！恭喜！","en":"Awesome! You finished up your mission! Congrats!","ja":"使命を成し遂げられたのですね!おめでとうございます!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_hoveren_2#originalText","id":"talk.vc.home_etc_hoveren_2","speaker":{"cn":"何布雷恩","en":"Hoveren","ja":"ホーブレン"},"text":{"cn":"礼物吗该先查看一下有没有危险物品……","en":"It’s a present. I went ahead and made sure it’s safe...","ja":"贈り物ですね先に危険物ではないか確認を……"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_hoveren_3#originalText","id":"talk.vc.home_etc_hoveren_3","speaker":{"cn":"何布雷恩","en":"Hoveren","ja":"ホーブレン"},"text":{"cn":"下个任务好像已经来了呢请务必赐我们可以一展身手的机会！","en":"We’ve got our next mission. Make sure to stop by!","ja":"次の任務が下りているようですねぜひ我らに活躍の場を!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_humbert_1#originalText","id":"talk.vc.home_etc_humbert_1","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"你这种货色居然能获得奖励……","en":"A reward? For the likes of you?","ja":"お前ごときが報奨をもらうとは……"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_humbert_2#originalText","id":"talk.vc.home_etc_humbert_2","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"礼物……反正内容也是不值一哂。","en":"A gift... Probably something trivial.","ja":"贈り物……どうせつまらぬものだろうさ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_humbert_3#originalText","id":"talk.vc.home_etc_humbert_3","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"不是有新使命吗？还不快去处理。","en":"You have a new mission, yes? Well, go get it done.","ja":"新しい使命があるのだろう?さっさとやってこい"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_iskahn_1#originalText","id":"talk.vc.home_etc_iskahn_1","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"完成使命了吗？这种程度一定要做到才行。","en":"Did you complete the mission? Well, it's the least I expect from you.","ja":"使命を果たしたかまあ、この程度はやってもらわないとな"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_iskahn_2#originalText","id":"talk.vc.home_etc_iskahn_2","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"好像有东西送来给你。什么，是食物吗？","en":"Something arrived for you. What is it, food?","ja":"お前に何か届いてるぞなんだ、食い物か?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_iskahn_3#originalText","id":"talk.vc.home_etc_iskahn_3","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"还有下一个使命吧？那就快点去做啊。","en":"You have a new mission, right? How about you get straight to it?","ja":"次の使命があるんだろ?さっさと取りかかったらどうだ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_jace_1#originalText","id":"talk.vc.home_etc_jace_1","speaker":{"cn":"杰伊斯","en":"Jayce","ja":"ジェイス"},"text":{"cn":"平安达成使命了啊！真不愧是你！","en":"You safely completed your mission! I knew you could do it!","ja":"無事使命を達成されたとか!さすがです!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_jace_2#originalText","id":"talk.vc.home_etc_jace_2","speaker":{"cn":"杰伊斯","en":"Jayce","ja":"ジェイス"},"text":{"cn":"有几件礼物好像送到了","en":"Seems like there’s a gift.","ja":"何やら贈り物が届いております"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_jace_3#originalText","id":"talk.vc.home_etc_jace_3","speaker":{"cn":"杰伊斯","en":"Jayce","ja":"ジェイス"},"text":{"cn":"似乎有新的使命！要出发时请务必带我们一起走","en":"There’s another mission! Let me know when you’re ready to depart!","ja":"新たな使命があるようです!出立の際は、ぜひ我らにお共させてください!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_kagemune_1#originalText","id":"talk.vc.home_etc_kagemune_1","speaker":{"cn":"影宗","en":"Kagemune","ja":"カゲムネ"},"text":{"cn":"有使命报酬，干得漂亮！","en":"You got a Mission reward. Way to go!","ja":"ミッション報酬だやったな!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_kagemune_2#originalText","id":"talk.vc.home_etc_kagemune_2","speaker":{"cn":"影宗","en":"Kagemune","ja":"カゲムネ"},"text":{"cn":"礼物送来啰。希望里面有放好东西。","en":"I hear you got a present. I hope there's something good inside.","ja":"プレゼントが来てるってよなにか良いもの入ってるといいな"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_kagemune_3#originalText","id":"talk.vc.home_etc_kagemune_3","speaker":{"cn":"影宗","en":"Kagemune","ja":"カゲムネ"},"text":{"cn":"听说有新的任务，我们去看一眼吧。","en":"A new Quest came in! Let's go see what it is.","ja":"新しいクエストだってよちょっと覗いてみよう"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_kibaou_1#originalText","id":"talk.vc.home_etc_kibaou_1","speaker":{"cn":"牙王","en":"Kibaou","ja":"キバオウ"},"text":{"cn":"使命报酬送来了，你去看看如何？","en":"You got a reward for clearing the Mission. Wanna check it out?","ja":"ミッション報酬が来とるで見てきたらどうや?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_kibaou_2#originalText","id":"talk.vc.home_etc_kibaou_2","speaker":{"cn":"牙王","en":"Kibaou","ja":"キバオウ"},"text":{"cn":"搞什么，是给你的礼物喔。快点收下吧。","en":"You got a gift or something. Go get it.","ja":"なんやお前に贈り物やはよ受け取れ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_kibaou_3#originalText","id":"talk.vc.home_etc_kibaou_3","speaker":{"cn":"牙王","en":"Kibaou","ja":"キバオウ"},"text":{"cn":"别偷懒了，我们去看下一个任务吧。","en":"Stop slacking off. A new Quest just came in!","ja":"さぼっとらんと次のクエスト見に行くで"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_kirito_1#originalText","id":"talk.vc.home_etc_kirito_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"去看看使命报酬吧！","en":"Let's go check out that Mission reward!","ja":"ミッション報酬見に行こうぜ!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_kirito_2#originalText","id":"talk.vc.home_etc_kirito_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"收到礼物啰。","en":"You've got a present.","ja":"プレゼントが届いてるぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_kirito_3#originalText","id":"talk.vc.home_etc_kirito_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"不知道有没有新的任务？我们去看看吧！","en":"Let's check to see if there are any new Quests!","ja":"新しいクエストがないか見に行こうぜ!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_kirito_child_1#originalText","id":"talk.vc.home_etc_kirito_child_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"喂，有完成工作的奖励喔！快点去看看吧！","en":"We got a reward for a job well done! Let's go check it out!","ja":"おい、仕事達成のご褒美があるぞ!早く見てみようぜ! "},"kind":"dialogue"},{"uid":"talk.vc.home_etc_kirito_child_2#originalText","id":"talk.vc.home_etc_kirito_child_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"礼物送来了喔。好羡慕喔～","en":"I hear you got a gift. Lucky you!","ja":"贈り物が届いてるってさうらやましいなー"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_kirito_child_3#originalText","id":"talk.vc.home_etc_kirito_child_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"好像发生了有趣的事情。要不要去看看？","en":"Something funny is going down out there. Wanna check it out?","ja":"なんか面白い事件が起きたみたいだ見に行かないか? "},"kind":"dialogue"},{"uid":"talk.vc.home_etc_klein_1#originalText","id":"talk.vc.home_etc_klein_1","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"完成使命啦？要确实领取报酬喔！","en":"You cleared the Mission, eh? Go get that reward, buddy!","ja":"ミッションクリアかちゃんと報酬はゲットしとけよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_klein_2#originalText","id":"talk.vc.home_etc_klein_2","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"说是礼物耶，你还是那么受欢迎呢。","en":"They say you've got a present. Look who's Mr. Popular!","ja":"プレゼントだとよ相変わらず人気者だな"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_klein_3#originalText","id":"talk.vc.home_etc_klein_3","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"好，下一个任务！我们来比谁比较快完成吧！","en":"Awesome, the next Quest is in! Let's bet on who finishes first!","ja":"よーし、次のクエストだ!どっちが早いか、競争だぜ!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_kuradeel_1#originalText","id":"talk.vc.home_etc_kuradeel_1","speaker":{"cn":"克拉帝尔","en":"Kuradeel","ja":"クラディール"},"text":{"cn":"使命的报酬送来了，这是你活跃的成果呢。","en":"You've got a reward for clearing the Mission. A testament to your glory.","ja":"ミッションの報酬が届いておりますご活躍の賜物ですな"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_kuradeel_2#originalText","id":"talk.vc.home_etc_kuradeel_2","speaker":{"cn":"克拉帝尔","en":"Kuradeel","ja":"クラディール"},"text":{"cn":"礼物？如果里面的东西危险，那就由我，来调换……","en":"A present? Let me check it, in case it's something dangerous.","ja":"プレゼント?ならば危険のないよう、この私が中を改めて……"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_kuradeel_3#originalText","id":"talk.vc.home_etc_kuradeel_3","speaker":{"cn":"克拉帝尔","en":"Kuradeel","ja":"クラディール"},"text":{"cn":"下个任务已经决定好了。请赶紧去确认内容吧。","en":"The next Mission is in. Let's look into it right away!","ja":"次の任務が決まりましたさっそく内容を確認してください"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_kureha_1#originalText","id":"talk.vc.home_etc_kureha_1","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"达成使命了！报酬是什么啊？拜托告诉我嘛－－","en":"You cleared the Mission! What was the reward? Come on, I want to know!","ja":"ミッションクリアだね!報酬はなんだったの?教えてほしいなー"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_kureha_2#originalText","id":"talk.vc.home_etc_kureha_2","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"听说你收到礼物了啊？受欢迎的人也真辛苦－－","en":"I hear you got a gift! Oh to be so popular...","ja":"贈り物が届いてるって人気者は辛いわねー"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_kureha_3#originalText","id":"talk.vc.home_etc_kureha_3","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"开放新任务啰！用来测试自己的本事正好？","en":"I new quest just came in! What about going in for a try?","ja":"新しいクエストが配信されたよ!腕試しにちょうどいいんじゃない?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_leafa_1#originalText","id":"talk.vc.home_etc_leafa_1","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"恭喜你达成使命！要持续向前进喔！","en":"Congrats on clearing that Mission. Let's keep pushing through!","ja":"ミッション達成、おめでとう! どんどん進んでいっちゃうね! "},"kind":"dialogue"},{"uid":"talk.vc.home_etc_leafa_2#originalText","id":"talk.vc.home_etc_leafa_2","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"收到礼物啰，打开看看吧？","en":"You've got a present. Wanna open it?","ja":"プレゼントが届いてるよ開けてみたら? "},"kind":"dialogue"},{"uid":"talk.vc.home_etc_leafa_3#originalText","id":"talk.vc.home_etc_leafa_3","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"出现新任务了！会是什么内容呢……","en":"A new Quest came out! I wonder what's in it.","ja":"新しいクエストが出現したよ! どんな内容だろう……"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_linel_1#originalText","id":"talk.vc.home_etc_linel_1","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"恭喜你达成使命。","en":"Congratulations on accomplishing the mission!","ja":"使命達成、おめでとうございます"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_linel_2#originalText","id":"talk.vc.home_etc_linel_2","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"这是……礼物吗？","en":"A gift...what could it be?","ja":"贈り物……なんでしょうか?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_linel_3#originalText","id":"talk.vc.home_etc_linel_3","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"好像有新的任务。你备受期待呢。","en":"I new mission has arrived. This proves people rely on you.","ja":"新しい任務だそうです期待されているんですね"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_lipia_1#originalText","id":"talk.vc.home_etc_lipia_1","speaker":{"cn":"莉琵雅","en":"Lipia","ja":"リピア"},"text":{"cn":"已经办妥所有工作了吗？真不愧是阁下。","en":"Have you already completed your mission? As expected from you, my Lord.","ja":"もう仕事を片付けたのですかさすがです、閣下"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_lipia_2#originalText","id":"talk.vc.home_etc_lipia_2","speaker":{"cn":"莉琵雅","en":"Lipia","ja":"リピア"},"text":{"cn":"有给阁下的礼物。送出人是谁呢……请好好确认。","en":"There is a gift addressed to you, my Lord. I wonder who the sender is... Please make sure who it's from.","ja":"閣下への贈り物がございます送り主は誰でしょうか……しっかり確認なさってください"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_lipia_3#originalText","id":"talk.vc.home_etc_lipia_3","speaker":{"cn":"莉琵雅","en":"Lipia","ja":"リピア"},"text":{"cn":"要做下一个工作了吗。请让我尽一点棉薄之力！","en":"Already on to the next mission, I see. Even if it is of little help, please let me assist you!","ja":"もう次のお仕事なんですね微力ながら、私もお手伝いさせていただきます!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_lisbeth_1#originalText","id":"talk.vc.home_etc_lisbeth_1","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"达成使命了，可以拿到什么报酬啊？","en":"You cleared the Mission! Did you get a reward?","ja":"ミッション達成ね報酬は何がもらえたの? "},"kind":"dialogue"},{"uid":"talk.vc.home_etc_lisbeth_2#originalText","id":"talk.vc.home_etc_lisbeth_2","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"咦，有礼物送来啰。你一定要打开来看看喔～","en":"You got a gift. You should check it sooner rather than later.","ja":"あれ、贈り物が届いてるわよちゃんとチェックしないとダメよー"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_lisbeth_3#originalText","id":"talk.vc.home_etc_lisbeth_3","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"有新任务呢，希望会掉落好材料。","en":"A new Quest came in. I hope some good materials drop from it.","ja":"新しいクエストねいい素材がドロップするといいなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_mary_1#originalText","id":"talk.vc.home_etc_mary_1","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"工作完成了？不愧是姊姊！那我去烧洗澡水啰。","en":"Have you finished the day's work? You're so fast, Sister! Well, then, let me go draw a bath for you.","ja":"お仕事終わったの?さすがお姉ちゃん!それじゃ、お風呂湧かすね"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_mary_2#originalText","id":"talk.vc.home_etc_mary_2","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"有姊姊的礼物喔，是谁送的呢？呵呵，姊姊有要好的人呢。","en":"There's a present for you, Sister. I wonder who it's from? Haha. Somebody sure is popular.","ja":"お姉ちゃんに贈り物だよ誰からなのかな?ふふ、仲良しな人がいるんだね"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_mary_3#originalText","id":"talk.vc.home_etc_mary_3","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"要开始工作了？这样啊……虽然寂寞，但妳工作要小心，加油喔！","en":"You have to go to work already? Oh... I'll miss you, but I hope you have a safe, productive day!","ja":"お仕事、始まっちゃうの?そっか……寂しいけどでも気をつけて、頑張ってね!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_medina_1#originalText","id":"talk.vc.home_etc_medina_1","speaker":{"cn":"梅蒂娜","en":"Medina","ja":"メディナ"},"text":{"cn":"达成任务了。虽然不是出于本意……我就称赞一下你吧。","en":"Mission complete, eh. This isn't my real intentions... but I'll acknowledge that.","ja":"任務達成だな本意ではないが……一応、褒めてやろう"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_medina_2#originalText","id":"talk.vc.home_etc_medina_2","speaker":{"cn":"梅蒂娜","en":"Medina","ja":"メディナ"},"text":{"cn":"礼物充满着送礼之人的心意。你就好好收下来吧。","en":"Presents carry with them, the thoughts of the sender in the box. Be sure to take this.","ja":"贈り物は、贈り主の思いが籠もっているちゃんと受け取ってこい"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_medina_3#originalText","id":"talk.vc.home_etc_medina_3","speaker":{"cn":"梅蒂娜","en":"Medina","ja":"メディナ"},"text":{"cn":"好像有新的任务。你要是不做的话，那就由我来处理掉吧？","en":"Looks like you have a new mission. If you don't do it, I'll have to take care of it, got it?","ja":"新しい任務があるようだなお前がやらないのなら私が片付けてしまうぞ?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_nergius_integrator_1#originalText","id":"talk.vc.home_etc_nergius_integrator_1","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"你完成使命了是吧？要是平时就这么认真做事，该有多好。","en":"You've accomplished your duties, I see. If only you were always so diligent.","ja":"使命を果たされたないつもそうして、真面目に取り組まれればいいものを"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_nergius_integrator_2#originalText","id":"talk.vc.home_etc_nergius_integrator_2","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"这是要给代表剑士大人的礼物。我想是没有危险，但请稍加提防。","en":"A present for you, Delegate. I doubt you will need it, but please use it just in case.","ja":"代表剣士殿に贈り物です危険なことはないと思いますが一応用心されよ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_nergius_integrator_3#originalText","id":"talk.vc.home_etc_nergius_integrator_3","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"下个任务已经在等你了。来，快点着手吧！","en":"The next mission awaits. Now, let's get started!","ja":"次なる任務が待っていますさあ、取り掛かりましょう!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_oberon_1#originalText","id":"talk.vc.home_etc_oberon_1","speaker":{"cn":"奥伯龙","en":"Oberon","ja":"オベイロン"},"text":{"cn":"喔，完成了吗？比我料想得还厉害嘛。","en":"Hoho, looks like you cleared it. You're more capable than I thought.","ja":"ほほお、ちゃんとクリアしたか思ったよりやるじゃないか"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_oberon_2#originalText","id":"talk.vc.home_etc_oberon_2","speaker":{"cn":"奥伯龙","en":"Oberon","ja":"オベイロン"},"text":{"cn":"来，这是给你的礼物。快打开吧。","en":"You got a present. Try opening it!","ja":"ほぅら、君にプレゼントだ開けてみたまえ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_oberon_3#originalText","id":"talk.vc.home_etc_oberon_3","speaker":{"cn":"奥伯龙","en":"Oberon","ja":"オベイロン"},"text":{"cn":"下一个工作已经来了吧。还不赶快去做！","en":"Our next job just came up! Let's hurry up and take it!","ja":"次の仕事があるだろうさっさと取りかかれ!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_phillia_1#originalText","id":"talk.vc.home_etc_phillia_1","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"恭喜你达成使命！真不愧是你！","en":"Congrats on clearing that mission! No surprise there!","ja":"ミッション達成おめでとうさすがだね!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_phillia_2#originalText","id":"talk.vc.home_etc_phillia_2","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"好像已经收到礼物了。好在意里面是什么喔。","en":"Looks like you got a gift! I wonder what's inside?","ja":"ギフトが届いてるみたいだよ中身が気になるなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_phillia_3#originalText","id":"talk.vc.home_etc_phillia_3","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"听说有新的任务。我们快去看吧！","en":"Let's check out if a new quest really did come in!","ja":"新しいクエスト、来たって噂だよほら、見に行こう!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_premiere_1#originalText","id":"talk.vc.home_etc_premiere_1","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"达成使命了呢。恭喜你！报酬已经送到啰！","en":"Congrats on clearing that mission! Here is your reward.","ja":"ミッションクリアですねおめでとうございます報酬が届いていますよ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_premiere_2#originalText","id":"talk.vc.home_etc_premiere_2","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"有你的礼物。赶紧打开来看看吧。","en":"A gift has arrived for you. Let's hurry up and open it!","ja":"あなたに贈り物が来ています早く開けてあげましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_premiere_3#originalText","id":"talk.vc.home_etc_premiere_3","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"好像有新任务耶。如果有跟野餐一样的任务一定很开心。","en":"I hear a new Quest just came in. It would be fun if the quest was like a picnic but...","ja":"新しいクエストがあるみたいですねピクニックのようなクエストだと楽しいのですが"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_rain_1#originalText","id":"talk.vc.home_etc_rain_1","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"达成使命了，好厉害喔！可以拿到什么报酬啊？","en":"You cleared the Mission! What was the reward?","ja":"ミッション達成、すごいね!報酬はなんだったの?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_rain_2#originalText","id":"talk.vc.home_etc_rain_2","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"收到礼物啰。我觉得还是赶快打开看看吧。","en":"You got a present. I think you should hurry up and open it!","ja":"プレゼントが届いてるよ早く開けてあげた方がいいと思うなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_rain_3#originalText","id":"talk.vc.home_etc_rain_3","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"好像有新任务耶？确认一下吧！","en":"I hear a new Quest just came in. Let's go check it out!","ja":"新しいクエストがあるかも!確認してこようよ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_raios_1#originalText","id":"talk.vc.home_etc_raios_1","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"达成使命了啊。哼，狂妄……","en":"You accomplished a mission? Hmph. Don't get too cocky.","ja":"使命達成かふん、生意気な……"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_raios_2#originalText","id":"talk.vc.home_etc_raios_2","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"那真的是给你的礼物吗？","en":"Is this gift really meant for you?","ja":"本当に貴様宛の贈り物なのか?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_raios_3#originalText","id":"talk.vc.home_etc_raios_3","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"我可不会让你在新使命上抢得先机喔？","en":"A new mission is in. I truly will not fall behind to the likes of you.","ja":"新しい使命では貴様に遅れはとらんぞ?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_renri_1#originalText","id":"talk.vc.home_etc_renri_1","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"达成任务了，恭喜你！拜托你做事真的让人很安心！","en":"Mission accomplished. Congratulations! I feel comfortable leaving things in your hands!","ja":"任務達成、おめでとう!君に任せておけば、安心だね!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_renri_2#originalText","id":"talk.vc.home_etc_renri_2","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"好像有礼物送来了。你还真是受欢迎呢。","en":"Looks like you got a gift. Look who's popular!","ja":"贈り物が届いているみたいだね君は人気者だなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_renri_3#originalText","id":"talk.vc.home_etc_renri_3","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"下次任务不知道会是怎样。先做好准备吧！","en":"I wonder what the next mission will be like? We need to do proper preparations!","ja":"次の任務、どんなものだろうねしっかり準備していこう!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_ronye_1#originalText","id":"talk.vc.home_etc_ronye_1","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"达成使命了，学长！太厉害了！","en":"Mission accomplished, sir! Splendidly done!","ja":"使命達成です、先輩! お見事です! "},"kind":"dialogue"},{"uid":"talk.vc.home_etc_ronye_2#originalText","id":"talk.vc.home_etc_ronye_2","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"有给学长的礼物。要帮您拿来吗？","en":"A gift arrived for you. Shall I go fetch it?","ja":"先輩への贈り物です運んできましょうか? "},"kind":"dialogue"},{"uid":"talk.vc.home_etc_ronye_3#originalText","id":"talk.vc.home_etc_ronye_3","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"是下一份使命呢，也请让我帮上一些忙吧。","en":"Your next Mission has arrived. Please, let me assist in any way I can.","ja":"次の使命ですね私も、なにかお手伝いをさせてください"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_rosalia_1#originalText","id":"talk.vc.home_etc_rosalia_1","speaker":{"cn":"罗莎莉雅","en":"Rosalia","ja":"ロザリア"},"text":{"cn":"有使命报酬啊？如果是好东西就交上来。","en":"There's a reward for clearing the Mission. If it's something nice, give it to me.","ja":"ミッション報酬があるのねいいものだったらアタシにちょうだいね"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_rosalia_2#originalText","id":"talk.vc.home_etc_rosalia_2","speaker":{"cn":"罗莎莉雅","en":"Rosalia","ja":"ロザリア"},"text":{"cn":"礼物？哪里的谁送的？","en":"A present? Who's it from? Give me names.","ja":"プレゼント?どこの誰からなの?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_rosalia_3#originalText","id":"talk.vc.home_etc_rosalia_3","speaker":{"cn":"罗莎莉雅","en":"Rosalia","ja":"ロザリア"},"text":{"cn":"希望下一个任务，内容够吸引人。","en":"I hope our next Quest is something juicy.","ja":"次のクエスト、おいしい内容だったらいいわね"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_sachi_1#originalText","id":"talk.vc.home_etc_sachi_1","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"完成使命了！报酬就是在奖励你的努力喔！","en":"You cleared the Mission! Get your reward! You deserve it.","ja":"ミッションクリアだね!報酬は頑張ったご褒美だよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_sachi_2#originalText","id":"talk.vc.home_etc_sachi_2","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"收到礼物啰。呵呵，是谁寄来的？","en":"You've got a present. Hehe, I wonder who it's from?","ja":"プレゼントが届いてるよふふ、誰から?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_sachi_3#originalText","id":"talk.vc.home_etc_sachi_3","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"新任务……希望是不怎么危险的任务。","en":"A new Quest is in... I hope it's not too dangerous.","ja":"新しいクエスト……あんまり危なくないといいなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_sakuya_1#originalText","id":"talk.vc.home_etc_sakuya_1","speaker":{"cn":"朔夜","en":"Sakuya","ja":"サクヤ"},"text":{"cn":"恭喜你达成使命，报酬是属于你的。","en":"Congrats on clearing that Mission! The reward is all yours.","ja":"ミッション達成おめでとう報酬は君のものだ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_sakuya_2#originalText","id":"talk.vc.home_etc_sakuya_2","speaker":{"cn":"朔夜","en":"Sakuya","ja":"サクヤ"},"text":{"cn":"好像有给你的礼物，是谁送的啊？","en":"You received a gift. So, who's it from?","ja":"君へのギフトがあるみたいだ誰からだい?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_sakuya_3#originalText","id":"talk.vc.home_etc_sakuya_3","speaker":{"cn":"朔夜","en":"Sakuya","ja":"サクヤ"},"text":{"cn":"新的任务，你愿意的话要不要一起解呢？","en":"You got in a new Quest! May I join you?","ja":"新しいクエストよかったら一緒にどうかな?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_scheta_1#originalText","id":"talk.vc.home_etc_scheta_1","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"达成任务了。恭喜你。","en":"Looks like mission accomplished. Congratulations.","ja":"任務達成みたいねおめでとう"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_scheta_2#originalText","id":"talk.vc.home_etc_scheta_2","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"有礼物送来了。","en":"Looks like you got a gift.","ja":"贈り物が届いているそうよ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_scheta_3#originalText","id":"talk.vc.home_etc_scheta_3","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"有下一次的任务了。","en":"Looks like the next mission is here.","ja":"次の任務があるみたい"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_selka_1#originalText","id":"talk.vc.home_etc_selka_1","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"你确实把工作做完了呢，真了不起。","en":"You finished your tasks, I see! I'm proud.","ja":"お仕事、ちゃんと終わらせたのねえらいじゃない"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_selka_2#originalText","id":"talk.vc.home_etc_selka_2","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"听说有礼物送来了！","en":"I hear you got a gift!","ja":"贈り物が届いてるんだって!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_selka_3#originalText","id":"talk.vc.home_etc_selka_3","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"你有听说新工作的事了吗？是怎样的工作呢？","en":"Did you hear about the new task? I wonder what sort of task it is?","ja":"新しいお仕事のお話、聞いた?どんな内容かしらね"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_seven_1#originalText","id":"talk.vc.home_etc_seven_1","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"Congratulation！完成使命了！","en":"That's a mission clear! Congratulations!","ja":"コングラチュレーション!ミッションクリアよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_seven_2#originalText","id":"talk.vc.home_etc_seven_2","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"早点拆开礼物是一种礼貌喔！来，快开礼物吧。","en":"You should always try and open your presents as soon as you get them. That is the proper way of doing things.","ja":"プレゼントは、できるだけ早く開けるのが礼儀よさあ、開けてきて"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_seven_3#originalText","id":"talk.vc.home_etc_seven_3","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"是不是有新任务啊？去看看吧。","en":"Isn't there a new Mission out? Let's go take a look!","ja":"新しい任務があるんじゃない?ほら、見に行きましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_shasta_1#originalText","id":"talk.vc.home_etc_shasta_1","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"顺利结束了吗。你比我想像中做得更好。","en":"Did you finish safe and sound? You did a better job than I thought.","ja":"無事に終えたか思った通り、いい仕事をしてくれたな"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_shasta_2#originalText","id":"talk.vc.home_etc_shasta_2","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"有你的礼物，一定是你喜欢的东西吧。","en":"There's a gift waiting for you. It will surely bring a smile to your face.","ja":"お前に贈り物が届いているきっと、お前が喜ぶものだろう"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_shasta_3#originalText","id":"talk.vc.home_etc_shasta_3","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"我有一件很适合你的工作，希望你能帮忙。","en":"I have just the perfect job for you. Please hear me out!","ja":"お前にふさわしい仕事があるぜひ頼まれてくれ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_silica_1#originalText","id":"talk.vc.home_etc_silica_1","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"恭喜你达成使命！","en":"Congrats on clearing that mission!","ja":"ミッション達成おめでとうございます! "},"kind":"dialogue"},{"uid":"talk.vc.home_etc_silica_2#originalText","id":"talk.vc.home_etc_silica_2","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"好像有礼物送来了呢，你果然很受欢迎……","en":"You got a gift. You're so popular...","ja":"贈り物が届いているようですねやっぱり人気者さんです……"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_silica_3#originalText","id":"talk.vc.home_etc_silica_3","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"好像有新的任务……我们一起去看看吧？","en":"Let's check to see if there are any new Quests!","ja":"新しいクエストがあるみたいで……一緒に見に行きませんか? "},"kind":"dialogue"},{"uid":"talk.vc.home_etc_sinon_1#originalText","id":"talk.vc.home_etc_sinon_1","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"完成使命啰，去确认报酬吧。","en":"You cleared the Mission. Let's go check out your reward.","ja":"ミッションクリアね報酬を確認しましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_sinon_2#originalText","id":"talk.vc.home_etc_sinon_2","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"听说这是给你的礼物，是谁送的呢？","en":"You have a present. I wonder who it's from?","ja":"あんたにプレゼントですって誰からかしら? "},"kind":"dialogue"},{"uid":"talk.vc.home_etc_sinon_3#originalText","id":"talk.vc.home_etc_sinon_3","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"我们赶紧去确认新任务吧。","en":"A new Quest came in. Let's go see what it is.","ja":"新しいクエスト、早めに確認しちゃいましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_siune_1#originalText","id":"talk.vc.home_etc_siune_1","speaker":{"cn":"朱涅","en":"Siune","ja":"シウネー"},"text":{"cn":"使命成功达成了呢！恭喜你。","en":"Congrats on clearing that Mission!","ja":"ミッション成功ですね!おめでとう"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_siune_2#originalText","id":"talk.vc.home_etc_siune_2","speaker":{"cn":"朱涅","en":"Siune","ja":"シウネー"},"text":{"cn":"听说礼物送来了。来，快打开来看看。","en":"You've got a present. Wanna open it?","ja":"プレゼントが届いてるんですってほら、開けてみたら?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_siune_3#originalText","id":"talk.vc.home_etc_siune_3","speaker":{"cn":"朱涅","en":"Siune","ja":"シウネー"},"text":{"cn":"有新任务唷。我们一起去看看吧。","en":"Let's check to see if there are any new Quests!","ja":"新しいクエストが来てるわ一緒に見に行きましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_sortiliena_1#originalText","id":"talk.vc.home_etc_sortiliena_1","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"你达成使命了吧，漂亮。","en":"You fulfilled your mission. I am so proud.","ja":"使命を達成したのだな見事だ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_sortiliena_2#originalText","id":"talk.vc.home_etc_sortiliena_2","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"有给你的礼物，尽早收下吧。","en":"There is a gift addressed to you. You should claim it as quickly as possible.","ja":"お前宛の贈り物だできれば、早く受け取ってやれ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_sortiliena_3#originalText","id":"talk.vc.home_etc_sortiliena_3","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"有新的使命下达了，我想你一定可以达成。","en":"A new mission has arrived. I am certain you can accomplish it.","ja":"新たな使命が下ったぞお前ならば達成できるだろう"},"kind":"dialogue"}]};
